INSERT IGNORE INTO `configurations` (`configuration_id`, `bundle_id`, `config_type`, `config_key`, `description`, `config_value`, `target`, `isPreLoginConfiguration`) VALUES ('298', 'NUO_CONFIG_BUNDLE', 'PREFERENCE', 'REMORTGAGE_DOC_CHECKLIST', 'List of products for which funding position should be enabled', '&emsp; 1.Proof of Identity\r\n&emsp;&emsp; a.Tax ID(mandatory)\r\n&emsp;&emsp; b.The ID which is entered under ID section to be pre populated\r\n(Any one document from below is Mandatory)\r\n&emsp;&emsp;&emsp;&emsp;  i. Driving License\r\n&emsp;&emsp;&emsp; &emsp; ii.Passport\r\n&emsp;&emsp;&emsp;&emsp;iii.Employee ID\r\n&emsp;&emsp;&emsp;&emsp; iv.Photo ID card issued by Local Government  <br>\r\n&emsp;2.Proof of Address : (Any one document from below is Mandatory)   \r\n&emsp;&emsp; a.Driving License    \r\n&emsp;&emsp; b.Passport    \r\n&emsp;&emsp; c.Utility Bills    \r\n&emsp;&emsp; d.Employer/HR letter   \r\n&emsp;&emsp; e.House Rent Contract <br>\r\n&emsp; 3.Proof of Income :    \r\n&emsp;&emsp;  a.For Status (Employment Status) - Salaried (Full Time Employee, Part Time Employee, Contract Employee, Casual Employee)    \r\n&emsp;&emsp;  &emsp;&emsp;     i.Pay-slips(mandatory) \r\n&emsp;&emsp;&emsp;    &emsp;  ii.Salary Account statement ( optional)    \r\n&emsp;&emsp; b.For Status(Employment Status) - Non-Salaried (Self-Employed, Retired,\r\n&emsp;&emsp;&emsp;Unemployed, Trainee)    \r\n&emsp;&emsp;&emsp;  &emsp;   i.Tax Return Statements(mandatory) \r\n&emsp;&emsp;&emsp;&emsp;   ii.Account Statements ( optional) <br>\r\n&emsp; 4.Supporting financial documents :    \r\n&emsp;&emsp; a.Bank statements    \r\n&emsp;&emsp; b.Credit card statement    \r\n&emsp;&emsp; c.Proof of deposit    \r\n&emsp;&emsp; d.Proof of Assets   \r\n&emsp;&emsp; e.Car finance agreement   \r\n&emsp;&emsp; f.Loan statements held with third parties <br>\r\n&emsp; 5.Product Document: First Time Buyer : (Add below documents if available)  \r\n&emsp;&emsp;  a.Existing Loan - Loan Outstanding Statement (Mandatory)    \r\n&emsp;&emsp;  b.Sale Agreement    \r\n&emsp;&emsp;  c.Additional Mortgage Document    \r\n&emsp;&emsp;  d.Existing loan - Repayment Schedule <br>\r\n&emsp; 6.Property Document : (Add below documents if available)\r\n&emsp;&emsp;    a.Sale Deed    \r\n&emsp;&emsp;    b.Parent Document    \r\n&emsp;&emsp;    c.Plan Approval/Layout Approval \r\n&emsp;&emsp;    d.Property Tax Receipt    \r\n&emsp;&emsp;   e.Electricity, Water and Drainage Certificate/Receipt', 'CLIENT', '1');
